const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function field(id,label,value='',type='text'){return `<label class="field"><span>${esc(label)}</span>${type==='textarea'?`<textarea id="${id}" rows="3">${esc(value)}</textarea>`:`<input id="${id}" type="${type}" value="${esc(value)}">`}</label>`}
export async function openModelSettings({config,modal,toast}){
 const baseUrl=(config.baseUrl||'http://127.0.0.1:4318').replace(/\/$/,'');
 const api=async(p,b)=>{const r=await fetch(baseUrl+p,{method:b?'POST':'GET',headers:b?{'Content-Type':'application/json'}:undefined,body:b?JSON.stringify(b):undefined,signal:AbortSignal.timeout(p==='/api/v1/model-test'?200000:40000)});const v=await r.json();if(!r.ok)throw new Error(v.error?.message||'配置接口调用失败');return v};
modal('大模型配置',`<p>正在读取本机后端配置…</p>`);try{let c=await api('/api/v1/model-config');modal('大模型配置',`<p>填写 OpenAI 兼容的 Chat Completions 接口。密钥保存到本机后端，不进入浏览器存储或成果文件。</p>${field('lm-url','API Base URL（通常以 /v1 结尾）',c.baseUrl)}<label class="field"><span>模型名称（以服务实际提供的 ID 为准）</span><input id="lm-model" list="lm-models" value="${esc(c.model)}" placeholder="填写模型 ID"><datalist id="lm-models">${['qwen3.8-max','Qwen3.8-Flash-Next-30B','DeepSeek-V4-Pro','GLM-5.2','Qwen3-235B-A22B'].map(x=>`<option value="${x}">参考资料中的模型名</option>`).join('')}</datalist></label><label class="field"><span>API Key · ${c.keyConfigured?'已配置，留空保留现有密钥':'尚未配置'}</span><input id="lm-key" type="password" autocomplete="new-password" placeholder="在此粘贴 API Key"></label><div class="model-settings-options"><label class="checklabel"><input id="lm-json" type="checkbox" ${c.jsonMode?'checked':''}>使用 JSON 模式（服务不支持 response_format 时取消）</label><label class="checklabel"><input id="lm-stream" type="checkbox" ${c.stream?'checked':''}>使用流式接收（支持千问深度思考）</label><label class="field"><span>深度思考参数</span><select id="lm-thinking">${[['auto','由服务默认决定（不发送参数）'],['on','开启 enable_thinking'],['off','关闭 enable_thinking']].map(([v,n])=>`<option value="${v}" ${(c.thinkingMode||'auto')===v?'selected':''}>${n}</option>`).join('')}</select></label></div><label class="checklabel model-settings-clear"><input id="lm-clear" type="checkbox">清除已有密钥</label><div id="letter-error" class="error-msg" role="status"></div>`,`<button data-action="close">关闭</button><button id="lm-test">测试已保存配置</button><button id="lm-save" class="primary">保存配置</button>`,true);$('#lm-save').onclick=async()=>{try{const v=await api('/api/v1/model-config',{expectedRevision:c.revision,baseUrl:$('#lm-url').value,model:$('#lm-model').value,apiKey:$('#lm-key').value,jsonMode:$('#lm-json').checked,stream:$('#lm-stream').checked,thinkingMode:$('#lm-thinking').value,clearKey:$('#lm-clear').checked});c=v;$('#lm-key').value='';$('#letter-error').textContent=(v.unchanged?'配置未变化，继续沿用当前配置。':'配置已保存，后续任务使用新配置。')+(v.keyConfigured?'密钥已配置。':'尚未填写密钥。');toast?.('大模型配置已保存')}catch(e){$('#lm-key').value='';$('#letter-error').textContent=e.message}};$('#lm-test').onclick=async()=>{try{$('#lm-test').disabled=true;$('#letter-error').textContent='正在测试已保存的配置…';const r=await api('/api/v1/model-test',{});$('#letter-error').textContent='连接成功，JSON 格式通过：'+r.model+'（'+(r.durationMs/1000).toFixed(1)+' 秒）'}catch(e){$('#letter-error').textContent=e.message}finally{if($('#lm-test'))$('#lm-test').disabled=false}}}catch(e){modal('大模型配置',`<p class="notice">无法读取后端：${esc(e.message)}。请确认本机后端 4318 正在运行，并在“大模型服务”中设置正确地址。</p>`)}}
